if (!window.LB) {
// Loudbook for Android - generated by tools/bundle_web.py; edit the sources, not this file.

// Loudbook: how to read each supported site. Shared, word for word, by the content script
// (reading the live page) and by the side panel's fetch-ahead reader (reading the NEXT chapter's
// HTML before it's opened), so both always agree on what a chapter's text is.
//
// Loaded as a classic content script before content.js, and imported for its side effect by
// lib/static-extract.js. Either way it defines globalThis.LB_SITES.
(() => {
  if (globalThis.LB_SITES) return;

  const BLOCK_SEL = 'p, h1, h2, h3, h4, h5, h6, li, blockquote, pre, tr, dt, dd';
  const SKIP_SEL = '.author-note-portlet, .author-note, nav, header, footer, aside, .comments, #comments, script, style, noscript, template, button';
  const BLOCK_TAGS = /^(P|DIV|LI|BLOCKQUOTE|H[1-6]|TR|UL|OL|PRE|DT|DD|HR|TABLE|SECTION|ARTICLE)$/;

  const q = (doc, sel) => { try { return doc.querySelector(sel); } catch { return null; } };
  const qa = (doc, sel) => { try { return [...doc.querySelectorAll(sel)]; } catch { return []; } };
  const txt = (el) => (el && el.textContent ? el.textContent.replace(/\s+/g, ' ').trim() : '');
  const abs = (href, url) => { try { return href ? new URL(href, url).href : null; } catch { return null; } };
  const titleParts = (doc, sep) => (doc.title || '').split(sep).map(s => s.trim()).filter(Boolean);

  // Text of an element, skipping anything hidden. <br> is a line break; table cells are joined
  // with " — " so a stat table reads "STR — 15". In lines mode, block elements also break lines.
  function textOf(root, isHidden, lines = false) {
    let out = '';
    const walk = (node) => {
      for (const n of node.childNodes) {
        if (n.nodeType === 3) { out += n.nodeValue; continue; }
        if (n.nodeType !== 1) continue;
        const tag = n.tagName;
        if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'NOSCRIPT' || tag === 'TEMPLATE' || tag === 'BUTTON') continue;
        if (tag === 'BR') { out += '\n'; continue; }
        if (isHidden(n)) continue;
        if (tag === 'TD' || tag === 'TH') { walk(n); out += ' — '; continue; }
        const br = lines && BLOCK_TAGS.test(tag);
        if (br) out += '\n';
        walk(n);
        if (br) out += '\n';
      }
    };
    walk(root);
    return out.replace(/[ \t\u00a0]+/g, ' ').replace(/ *— *(\n|$)/g, '$1').replace(/ *\n */g, '\n').replace(/\n{2,}/g, '\n').trim();
  }
  const speakable = (t) => /[\p{L}\p{N}]/u.test(t);

  // ---------------------------------------------------------------- generic fallbacks
  function genericContainer(doc, isHidden) {
    let best = null, bestScore = 0;
    const seen = new Set();
    for (const p of doc.querySelectorAll('p')) {
      const parent = p.parentElement;
      if (!parent || seen.has(parent)) continue;
      seen.add(parent);
      if (isHidden(parent)) continue;
      let score = 0;
      for (const c of parent.children) if (c.tagName === 'P' && !isHidden(c)) score += (c.textContent || '').trim().length;
      if (score > bestScore) { bestScore = score; best = parent; }
    }
    if (best) return best;
    // no paragraphs at all: some sites put a whole chapter in one element, separated by <br>
    for (const el of doc.querySelectorAll('div, td, section, article')) {
      if (isHidden(el)) continue;
      let brs = 0;
      for (const c of el.children) if (c.tagName === 'BR') brs++;
      if (brs > bestScore) { bestScore = brs; best = el; }
    }
    return bestScore >= 5 ? best : null;
  }
  function genericTitle(doc) {
    const h1 = q(doc, 'article h1, main h1, h1');
    if (h1 && txt(h1)) return txt(h1);
    return titleParts(doc, /\s[|–-]\s/)[0] || '';
  }
  function genericNav(doc, url, dir, accept) {
    const rel = q(doc, `link[rel="${dir}"][href], a[rel="${dir}"][href]`);
    if (rel && (!accept || accept(rel.getAttribute('href')))) return abs(rel.getAttribute('href'), url);
    const word = dir === 'next' ? '(next|continue to next part)' : '(prev|previous)';
    const re = new RegExp(`^\\s*(\\W\\s*)?${word}(\\s*(chapter|part|page))?(\\s*\\W)?\\s*$`, 'i');
    for (const a of doc.querySelectorAll('a[href]')) {
      if (!re.test(txt(a))) continue;
      if (a.hasAttribute('disabled') || a.classList.contains('disabled')) continue;
      const href = a.getAttribute('href') || '';
      if (href === '#' || href.startsWith('javascript:')) continue;
      if (accept && !accept(href)) continue;
      return abs(href, url);
    }
    return null;
  }

  // ---------------------------------------------------------------- the sites
  // Every field is optional. roots: the element(s) holding the chapter (none = not a chapter
  // page, so nothing is read). lines: the text is <br>-separated rather than in <p>s.
  // textApi: a same-site URL that returns the whole chapter's HTML (for sites that load long
  // chapters in pieces as you scroll).
  const SITES = [
    {
      id: 'royalroad', name: 'Royal Road', hosts: /(^|\.)royalroad\.com$/,
      roots: (doc) => [q(doc, '.chapter-inner.chapter-content, .chapter-content, .chapter-inner')],
      title: (doc) => txt(q(doc, '.fic-header h1, h1.font-white, .chapter-title')),
      fiction: (doc) => txt(q(doc, '.fic-header h2')) || titleParts(doc, '|')[1] || '',
      navAccept: (href) => /\/chapter\//.test(href),
    },
    {
      // Checked against Scribble Hub's known layout; its bot check blocked a live look.
      id: 'scribblehub', name: 'Scribble Hub', hosts: /(^|\.)scribblehub\.com$/,
      roots: (doc) => [q(doc, '#chp_raw, .chp_raw')],
      skip: '.wi_authornotes, .wi_news',
      title: (doc) => txt(q(doc, '.chapter-title')),
      fiction: (doc) => txt(q(doc, '.chp_byauthor ~ a, a.chp_title, .wi_fic_title')) || titleParts(doc, '|')[1] || '',
      next: (doc, url) => abs(q(doc, 'a.btn-next:not(.disabled)')?.getAttribute('href'), url),
      prev: (doc, url) => abs(q(doc, 'a.btn-prev:not(.disabled)')?.getAttribute('href'), url),
    },
    {
      id: 'ao3', name: 'Archive of Our Own', hosts: /(^|\.)archiveofourown\.org$/,
      roots: (doc) => [q(doc, '#chapters')],
      skip: '.landmark, .notes, .end, .preface, .afterword',
      title: (doc) => txt(q(doc, '#chapters .chapter.preface h3.title')) || txt(q(doc, 'h2.title.heading')),
      fiction: (doc) => txt(q(doc, 'h2.title.heading')),
      next: (doc, url) => abs(q(doc, 'li.chapter.next a')?.getAttribute('href'), url),
      prev: (doc, url) => abs(q(doc, 'li.chapter.previous a')?.getAttribute('href'), url),
    },
    {
      id: 'ffn', name: 'FanFiction.net', hosts: /(^|\.)(fanfiction\.net|fictionpress\.com)$/,
      roots: (doc) => [q(doc, '#storytext')],
      fiction: (doc) => txt(q(doc, '#profile_top b.xcontrast_txt, #profile_top b')),
      title: (doc) => {
        const o = q(doc, '#chap_select option[selected], select#chap_select option:checked');
        return o ? txt(o).replace(/^\d+\.\s*/, '') : txt(q(doc, '#profile_top b.xcontrast_txt, #profile_top b'));
      },
      // /s/<story>/<chapter>/<slug>: the chapter list says how many there are
      next: (doc, url) => ffnStep(doc, url, +1),
      prev: (doc, url) => ffnStep(doc, url, -1),
    },
    {
      id: 'wattpad', name: 'Wattpad', hosts: /(^|\.)wattpad\.com$/,
      roots: (doc, url) => (/wattpad\.com\/\d{5,}/.test(url) ? [q(doc, '.page pre, pre') || q(doc, 'body')] : [null]),
      textApi: (url) => { const m = String(url).match(/wattpad\.com\/(\d{5,})/); return m ? `https://www.wattpad.com/apiv2/?m=storytext&id=${m[1]}` : null; },
      skip: '.component-wrapper, .comment-marker, .num-comment',
      title: (doc) => { const p = titleParts(doc, ' - '); return p.length >= 3 ? p.slice(1, -1).join(' - ') : txt(q(doc, 'h1.h2')); },
      fiction: (doc) => titleParts(doc, ' - ')[0] || '',
      // its rel=next points at page 2 of the SAME part; the next part is this button
      next: (doc, url) => abs((qa(doc, 'a[href]').find(a => /next part/i.test(txt(a))) || {}).getAttribute?.('href'), url),
      prev: () => null,
    },
    {
      id: 'webnovel', name: 'WebNovel', hosts: /(^|\.)webnovel\.com$/,
      roots: (doc, url) => {
        const id = (String(url).match(/(\d{8,})\/?(?:[?#].*)?$/) || [])[1];
        return [(id && q(doc, `.cha-words._font_${id}`)) || q(doc, '.cha-words')];
      },
      title: (doc) => txt(q(doc, '.cha-tit h1, h1')),
      fiction: (doc) => (doc.title || '').replace(/\s*-\s*WebNovel\s*$/i, '').split(/\s+Chapter\s+\d/i)[0].trim(),
    },
    {
      id: 'wuxiaworld', name: 'Wuxiaworld', hosts: /(^|\.)wuxiaworld\.com$/,
      roots: (doc) => [q(doc, '.chapter-content')],
      title: (doc) => titleParts(doc, ' - ').slice(1).join(' - ') || txt(q(doc, 'h4')),
      fiction: (doc) => titleParts(doc, ' - ')[0] || '',
    },
    {
      // XenForo story forums. Built from XenForo's standard layout; Cloudflare blocked a live
      // look. Reader mode (/reader/) holds only the story posts; on a normal thread page only
      // threadmarked posts are read, so replies aren't.
      id: 'xenforo', name: 'SpaceBattles / Sufficient Velocity / QQ',
      hosts: /(^|\.)(spacebattles\.com|sufficientvelocity\.com|questionablequesting\.com)$/,
      roots: (doc, url) => {
        const posts = qa(doc, 'article.message');
        if (!posts.length) return [null];
        const story = /\/(reader|threadmarks)\b/.test(url) ? posts : posts.filter(a => a.classList.contains('hasThreadmark'));
        return (story.length ? story : posts.slice(0, 1)).map(a => q(a, '.message-body .bbWrapper, .bbWrapper')).filter(Boolean);
      },
      lines: true,
      skip: '.bbCodeBlock-expandLink, .bbCodeSpoiler-button, .message-signature, .js-selectToQuoteEnd',
      postTitle: (root) => txt(root.closest('article') && root.closest('article').querySelector('.threadmarkLabel')),
      title: (doc) => txt(q(doc, '.threadmarkLabel')) || txt(q(doc, 'h1.p-title-value')),
      fiction: (doc) => txt(q(doc, 'h1.p-title-value')),
      next: (doc, url) => abs(q(doc, 'a.pageNav-jump--next')?.getAttribute('href'), url),
      prev: (doc, url) => abs(q(doc, 'a.pageNav-jump--prev')?.getAttribute('href'), url),
    },
  ];

  function ffnStep(doc, url, d) {
    const m = new URL(url).pathname.match(/^\/s\/(\d+)\/(\d+)(\/[^/?#]*)?/);
    if (!m) return null;
    const n = Number(m[2]) + d;
    const count = qa(doc, 'select#chap_select option').length / (qa(doc, 'select#chap_select').length || 1);
    if (n < 1 || n > count) return null;
    return new URL(`/s/${m[1]}/${n}${m[3] || ''}`, url).href;
  }

  function profileFor(url) {
    let host = '';
    try { host = new URL(url).hostname; } catch {}
    return SITES.find(s => s.hosts.test(host)) || null;
  }

  // Blocks of one root. Normal mode: every leaf block element is a paragraph. Lines mode (and
  // the fallback when a root has no paragraph elements): each line of text is a paragraph, all
  // sharing the root element; `base` counts the non-space characters before each line so the
  // page can find the sentence inside the shared element.
  const squashLen = (t) => t.replace(/[\s\u200b-\u200d\ufeff]+/g, '').length;
  function blocksOf(root, isHidden, skip, lines) {
    const out = [];
    const skipSel = skip ? SKIP_SEL + ', ' + skip : SKIP_SEL;
    if (!lines) {
      const leaves = [...root.querySelectorAll(BLOCK_SEL)].filter(el => !el.querySelector(BLOCK_SEL));
      for (const el of leaves) {
        if (el.closest(skipSel)) continue;
        if (el.tagName === 'TD' || el.tagName === 'TH') continue;
        if (isHidden(el)) continue;
        const text = textOf(el, (n) => isHidden(n) || (skip && n.matches && n.matches(skip)));
        if (speakable(text)) out.push({ el, text });
      }
      if (out.length) return out;
    }
    const all = textOf(root, (n) => isHidden(n) || (n.matches && n.matches(skipSel)), true);
    let base = 0;
    for (const line of all.split('\n').map(s => s.trim()).filter(Boolean)) {
      if (speakable(line)) out.push({ el: root, text: line, shared: true, base });
      base += squashLen(line);
    }
    return out;
  }

  // Everything Loudbook needs from a chapter page. isHidden decides what counts as invisible:
  // the live page asks the browser; a fetched page has had its hidden rules applied already.
  function extract(doc, url, isHidden = () => false) {
    const site = profileFor(url);
    let roots;
    if (site) roots = (site.roots(doc, url) || []).filter(Boolean);
    else { const c = genericContainer(doc, isHidden); roots = c ? [c] : []; }
    const blocks = [];
    for (const root of roots) {
      const head = site && site.postTitle ? site.postTitle(root) : '';
      if (head && roots.length > 1) blocks.push({ el: root, text: head, shared: true, base: -1, heading: true });
      blocks.push(...blocksOf(root, isHidden, site && site.skip, !!(site && site.lines)));
    }
    const nav = (dir) => {
      if (site && site[dir]) { const v = site[dir](doc, url); if (v !== undefined) return v; }
      return genericNav(doc, url, dir, site && site.navAccept);
    };
    return {
      site: site ? site.id : 'generic',
      siteName: site ? site.name : '',
      roots,
      blocks,
      title: (site && site.title && site.title(doc, url)) || genericTitle(doc),
      fiction: (site && site.fiction && site.fiction(doc, url)) || (() => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch { return ''; } })(),
      nextUrl: nav('next'),
      prevUrl: nav('prev'),
      textApi: site && site.textApi ? site.textApi(url) : null,
    };
  }

  // Blocks from a site's "whole chapter" HTML (see textApi). Each paragraph keeps its id so the
  // live page can find it once it has loaded.
  function blocksFromApiHtml(html, skip) {
    const d = new DOMParser().parseFromString('<body>' + html + '</body>', 'text/html');
    const out = [];
    for (const p of d.querySelectorAll('p, h1, h2, h3, h4, li, blockquote')) {
      if (p.querySelector('p, li, blockquote')) continue;
      const text = textOf(p, (n) => !!(skip && n.matches && n.matches(skip)));
      if (speakable(text)) out.push({ text, pid: p.getAttribute('data-p-id') || '' });
    }
    return out;
  }

  globalThis.LB_SITES = { SITES, profileFor, extract, textOf, blocksFromApiHtml, genericContainer, BLOCK_SEL };
})();

const LBChunk = (() => {
// Split chapter blocks into speakable chunks.
// Kokoro sounds best on a sentence or two at a time (and has a hard input limit), and
// Chrome's own voices cut out on long utterances, so both engines get the same chunks.

const ABBREV = /\b(Mr|Mrs|Ms|Dr|Prof|Sr|Jr|St|Mt|vs|etc|e\.g|i\.e|No|Vol|Ch|Lt|Col|Gen|Sgt|Capt|Rev|Hon|approx|lvl|Lv|Lvl|HP|MP)\.$/i;
const MAX = 320;       // hard ceiling per chunk
const TARGET = 200;    // merge short sentences up to about this

function splitSentences(text) {
  const out = [];
  // a sentence ends at . ! ? … (optionally followed by closing quotes/brackets) + space
  const re = /[^.!?…]+(?:[.!?…]+["'”’)\]]*|$)\s*/g;
  let m, carry = '';
  while ((m = re.exec(text)) !== null) {
    if (!m[0]) { re.lastIndex++; continue; }
    const piece = carry + m[0];
    const trimmed = piece.trim();
    // don't end a sentence on "Mr." or "3." (as in 3.5) or a lone initial "J."
    if (ABBREV.test(trimmed) || /\b[A-Z]\.$/.test(trimmed) || /\d\.$/.test(trimmed) && /^\d/.test(text.slice(re.lastIndex))) {
      carry = piece; continue;
    }
    carry = '';
    if (trimmed) out.push(trimmed);
  }
  if (carry.trim()) out.push(carry.trim());
  // "Run!" she said.  /  He ran... and ran.  -- a lowercase start means the sentence
  // didn't really end, so glue it back on
  const merged = [];
  for (const s of out) {
    if (merged.length && /^["'\u201c\u2018(]?\p{Ll}/u.test(s)) merged[merged.length - 1] += ' ' + s;
    else merged.push(s);
  }
  return merged;
}

function splitLong(s) {
  if (s.length <= MAX) return [s];
  const parts = [];
  let rest = s;
  while (rest.length > MAX) {
    const window = rest.slice(0, MAX);
    let cut = Math.max(window.lastIndexOf('; '), window.lastIndexOf(', '), window.lastIndexOf(' — '), window.lastIndexOf(': '));
    if (cut < MAX * 0.4) cut = window.lastIndexOf(' ');
    if (cut < MAX * 0.3) cut = MAX;
    parts.push(rest.slice(0, cut + 1).trim());
    rest = rest.slice(cut + 1).trim();
  }
  if (rest) parts.push(rest);
  return parts;
}

function clean(t) {
  return t
    .replace(/\s+/g, ' ')
    .replace(/[\u200b\u200c\u200d\ufeff]/g, '')
    .replace(/_{3,}|={3,}|-{4,}/g, ' ')        // divider lines
    .trim();
}

// blocks: [{i, text}]  ->  chunks: [{block, text}]
function chunkBlocks(blocks) {
  const chunks = [];
  for (const b of blocks) {
    const text = clean(b.text);
    if (!/[\p{L}\p{N}]/u.test(text)) continue;
    const sentences = splitSentences(text).flatMap(splitLong);
    let buf = '';
    for (const s of sentences) {
      if (!buf) { buf = s; continue; }
      if ((buf + ' ' + s).length <= TARGET) buf += ' ' + s;
      else { chunks.push({ block: b.i, text: buf }); buf = s; }
    }
    if (buf) chunks.push({ block: b.i, text: buf });
  }
  return chunks;
}

const _internal = { splitSentences, splitLong, clean };

return { chunkBlocks };
})();

const LBSay = (() => {
// What the voice is actually given to say. The page text is shown and highlighted as written;
// this only changes what is spoken:
//  - the reader's own pronunciation fixes ("Tavi = Tah-vee"), whole words, any case;
//  - a few clean-ups for how web fiction is written, which otherwise come out badly:
//    "Noooooo" / "Ahhhhhh" (the voice tries to say every letter), "!!!!" and "?!?!",
//    "HP: 120/150" (read as "120 slash 150"), "Lv. 5" / "Lvl 5", Roman numerals, stat names, units,
//    "2x", "#1", "-5", "2-3", "*sigh*", stammers ("N-no"), arrows. Checked by listening to what the
//    voice makes of it (tools: the pronunciation lab in Loudbook-android/test/say).

// Parse the settings box: one fix per line, "word = say it like this" (also accepts -> or →).
function parseFixes(text) {
  const out = [];
  for (const raw of String(text || '').split('\n')) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const m = line.match(/^(.+?)\s*(?:=|->|→)\s*(.*)$/);
    if (!m) continue;
    const from = m[1].trim(), to = m[2].trim();
    if (from) out.push({ from, to });
  }
  return out;
}

const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function makeSayer(fixes = [], { tidy: doTidy = true } = {}) {
  const rules = fixes
    .filter(f => f.from)
    .sort((a, b) => b.from.length - a.from.length)          // longest first: "Mr Tavi" before "Tavi"
    .map(f => {
      const pre = /^[\p{L}\p{N}_]/u.test(f.from) ? '(?<![\\p{L}\\p{N}_])' : '';
      const post = /[\p{L}\p{N}_]$/u.test(f.from) ? '(?![\\p{L}\\p{N}_])' : '';
      return { re: new RegExp(pre + esc(f.from) + post, 'giu'), to: f.to };
    });
  return function say(text) {
    let t = String(text || '');
    for (const r of rules) t = t.replace(r.re, r.to);
    return doTidy ? tidy(t) : t;
  };
}

// Roman numerals: "Chapter IV" -> "Chapter 4", "Tier III" -> "Tier 3", "Henry VIII" -> "Henry the 8th"
// (the voice otherwise says "Roman four", and a run of I's used to get squashed).
const ROMAN = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
const COUNTED = /^(chapter|book|part|volume|vol\.?|act|arc|season|episode|tier|rank|class|grade|level|stage|phase|type|mark|mk\.?|model|gen|generation|war|floor|circle|realm|step|star|ch\.?)$/i;
function romanValue(r) {
  const v = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let n = 0;
  for (let i = 0; i < r.length; i++) { const a = v[r[i]], b = v[r[i + 1]] || 0; n += a < b ? -a : a; }
  return n;
}
function romans(t) {
  return t.replace(/\b([A-Z][\w.]*)(\s+)([IVXLCDM]+)\b(?![''’]\w)/g, (m, before, sp, r) => {
    if (!ROMAN.test(r)) return m;
    if (COUNTED.test(before)) return before + sp + romanValue(r);
    // after a name: a king, a pope, a ship. Only two letters or more ("Henry V" stays, "I" is a word).
    if (r.length >= 2 && /^[A-Z][a-z]+$/.test(before)) return before + sp + 'the ' + romanValue(r) + ord(romanValue(r));
    return m;
  });
}
const ord = (n) => (n % 100 >= 11 && n % 100 <= 13) ? 'th' : ['th', 'st', 'nd', 'rd'][n % 10] || 'th';

// LitRPG stat names, said in full when they're clearly stats ("STR: 12", "AGI +3")
const STATS = { STR: 'Strength', AGI: 'Agility', DEX: 'Dexterity', INT: 'Intelligence', VIT: 'Vitality', END: 'Endurance',
  WIS: 'Wisdom', CHA: 'Charisma', LUK: 'Luck', LCK: 'Luck', PER: 'Perception', CON: 'Constitution', SPD: 'Speed',
  DEF: 'Defense', ATK: 'Attack', MAG: 'Magic', RES: 'Resistance', SPI: 'Spirit', FOC: 'Focus', WIL: 'Willpower' };
const TITLES = { Mr: 'Mister', Mrs: 'Missus', Ms: 'Miz', Dr: 'Doctor', Prof: 'Professor', Capt: 'Captain', Sgt: 'Sergeant',
  Lt: 'Lieutenant', Gen: 'General', Col: 'Colonel', Rev: 'Reverend', Fr: 'Father', Sr: 'Senior', Jr: 'Junior', Gov: 'Governor',
  Sen: 'Senator', Rep: 'Representative', Pres: 'President', Insp: 'Inspector', Det: 'Detective', Cpl: 'Corporal', Pvt: 'Private',
  Adm: 'Admiral', Cmdr: 'Commander', Maj: 'Major', Hon: 'Honorable' };
const UNITS = { km: ['kilometer', 'kilometers'], cm: ['centimeter', 'centimeters'], mm: ['millimeter', 'millimeters'],
  m: ['meter', 'meters'], kg: ['kilogram', 'kilograms'], g: ['gram', 'grams'], lb: ['pound', 'pounds'], lbs: ['pound', 'pounds'],
  ft: ['foot', 'feet'], mph: ['mile per hour', 'miles per hour'], 'km/h': ['kilometer per hour', 'kilometers per hour'],
  kph: ['kilometer per hour', 'kilometers per hour'], mi: ['mile', 'miles'], min: ['minute', 'minutes'], hr: ['hour', 'hours'], hrs: ['hour', 'hours'] };

function tidy(t) {
  // scene breaks and decorations ("***", "~~~", "=== Chapter 5 ===", "---o0o---", "◇◇◇"): silent
  t = t.replace(/([~=*#_<>+\-—–])\1{2,}/g, ' ').replace(/(^|\s)[oO0xX]{3}(?=\s|$)/g, '$1 ').replace(/[◇◆◈❖•·♦♢❦☆★✦✧♪♫]+/gu, ' ')
    .replace(/<3\b/g, '');
  if (!/[\p{L}\p{N}]/u.test(t)) return '';
  return romans(t.replace(/\s{2,}/g, ' ').trim())
    // a run of one letter: "Noooooo" -> "Noo", "Hmmmm" -> "Hmm" (but not Roman numerals, and not
    // a rank like "SSS")
    .replace(/(\p{L})\1{2,}/gu, (m, c) => (/[IVXLCDM]/.test(c) || (m.length === 3 && c === c.toUpperCase()) ? m : c + c))
    .replace(/([!?])[!?]{2,}/g, (m) => (m.includes('?') && m.includes('!') ? '?!' : m[0]))
    .replace(/\.{4,}/g, '...')
    // the voice drops "..." altogether (no pause at all): a beat instead, or a full stop before a new sentence
    .replace(/(\.\.\.|…)(?=\s*["'”’)\]]*\s*$)/gu, '.')
    .replace(/(\.\.\.|…)\s*(?=\p{Lu})/gu, '. ').replace(/(\p{L}|\p{N}|,)\s*(\.\.\.|…)\s*(?=[\p{Ll}\p{N}])/gu, '$1; ')
    // titles: "Mr. Smith" (the period made the voice stop as if the sentence had ended)
    .replace(/\b(Mr|Mrs|Ms|Dr|Prof|Capt|Sgt|Lt|Gen|Col|Rev|Fr|Sr|Jr|Gov|Sen|Rep|Pres|Insp|Det|Cpl|Pvt|Adm|Cmdr|Maj|Hon)\.(?=\s+\p{Lu})/gu,
      (m, t) => TITLES[t])
    // *sigh*, **bold**: the voice would say "asterisk"
    .replace(/\*+([^*\n]{1,80}?)\*+/g, '$1').replace(/(^|\s)\*+(?=\s|$)/g, '$1')
    // stammers: "N-no" -> "no", "S-stop" -> "stop" (otherwise "en no", "ess stop")
    .replace(/\b(\p{L})-(\1)/giu, (m, a, b) => (a === a.toUpperCase() ? b.toUpperCase() : b))
    // arrows in stat changes: "15 → 17"
    .replace(/\s*(?:→|->|⟶|=>)\s*/g, ' to ')
    .replace(/\b(?:Lv|Lvl|LVL|LV)\.?\s*(?=\d)/g, 'Level ')
    .replace(/\b([A-Z]{3})(?=\s*(?::|\+|-|—|–|\d))/g, (m, k) => STATS[k] || m)
    .replace(/(^|[\s(\[])\+(?=\d)/g, '$1plus ')                     // +5 Agility
    .replace(/(^|[\s(\[])[-−](?=\d)/g, '$1minus ')                  // -5 degrees
    .replace(/#(?=\d)/g, 'number ')                                // Rank #1
    .replace(/\b(\d+)x\b/g, '$1 times').replace(/\bx(\d+)\b/g, 'times $1')   // 2x damage, x3
    .replace(/\$(\d+(?:\.\d+)?)\s?(k|K|m|M|bn|b|B)\b/g, (m, n, u) => n + ' ' + { k: 'thousand', m: 'million', b: 'billion', bn: 'billion' }[u.toLowerCase()] + ' dollars')
    .replace(/\b(\d+(?:\.\d+)?)\s?k\b/g, '$1 thousand')            // 10k
    .replace(/\b(\d+)'\s?(\d+)(?:"|''|”)/g, '$1 foot $2')           // 6'2"
    .replace(/\b(\d+)\s?(am|pm|AM|PM|a\.m\.|p\.m\.)(?![\w])/g, (m, n, ap) => n + ' ' + ap.replace(/\./g, '').toUpperCase())
    .replace(/(^|[^$\w])(\d+(?:\.\d+)?)\s?(km\/h|km|cm|mm|kg|lbs|lb|mph|kph|ft|mi|min|hrs|hr|m|g)\b(?!\/)/g,
      (m, pre, n, u) => pre + n + ' ' + UNITS[u][n === '1' ? 0 : 1])
    .replace(/\b1\/2(?=\s+(?:of|a|an|the)\b)/g, 'half').replace(/\b1\/3(?=\s+(?:of|a|an|the)\b)/g, 'a third')
    .replace(/\b1\/4(?=\s+(?:of|a|an|the)\b)/g, 'a quarter')
    .replace(/(\d)\s*\/\s*(\d)/g, '$1 of $2')                      // 120/150 -> 120 of 150
    .replace(/\b(\d+)\s?[-–]\s?(\d+)\b(?![-–/]\d)/g, '$1 to $2')     // 2-3 hours
    .replace(/\b(\d+):(\d)\b(?!\d)/g, '$1 to $2')                  // a 3:1 ratio (times have two digits)
    .replace(/\bCh\.\s*(?=\d)/g, 'Chapter ').replace(/\bVol\.\s*(?=\d)/g, 'Volume ').replace(/\bNo\.\s*(?=\d)/g, 'Number ')
    .replace(/\bapprox\.(?=\s)/gi, 'approximately').replace(/(^|\s)w\/(?=\s)/g, '$1with').replace(/\bb\/c\b/g, 'because')
    .replace(/([£€])(\d+)(?:\.(\d\d))?\b/g, (m, c, n, p) => {
      const [one, many] = c === '£' ? ['pound', 'pounds'] : ['euro', 'euros'];
      return n + ' ' + (n === '1' ? one : many) + (p && +p ? ' ' + (+p) : '');
    })
    .replace(/\bvs\.?(?=\s)/gi, 'versus').replace(/\bi\.e\.(?=[\s,])/gi, 'that is')
    .replace(/\bSt\.(?=\s+[A-Z])/g, 'Saint').replace(/\b([A-Z][a-z]+)\s+St\.(?!\w)/g, '$1 Street');
}

return { parseFixes, makeSayer, tidy };
})();

// Loudbook for Android: the part that runs inside the chapter page (in the app's WebView).
// Built into assets/web/loudbook.js together with the extension's sites.js, lib/chunk.js and
// lib/say.js (see build.sh), so the phone reads pages exactly like the Chrome extension.
//
// Talks to the app through window.LoudbookNative (a Java object):
//   LoudbookNative.onChapter(json)   - the chapter, split into sentences, ready to speak
//   LoudbookNative.onNoChapter(json) - this page isn't a chapter
(() => {
  if (window.LB) return;
  const S = globalThis.LB_SITES;

  // ---------- visibility (same rules as the extension's content.js) ----------
  function hiddenEl(el) {
    if (!(el instanceof Element)) return false;
    if (el.getClientRects().length === 0) return true;
    const cs = getComputedStyle(el);
    if (cs.visibility === 'hidden' || cs.visibility === 'collapse') return true;
    if (parseFloat(cs.opacity) === 0) return true;
    if (parseFloat(cs.fontSize) === 0) return true;
    if (cs.clipPath && cs.clipPath !== 'none' && /inset\(\s*(50|100)%/.test(cs.clipPath)) return true;
    const r = el.getBoundingClientRect();
    if (cs.position === 'absolute' || cs.position === 'fixed') {
      if (r.right < -500 || r.bottom < -500 || r.left > innerWidth + 5000) return true;
      if (r.width <= 1 && r.height <= 1) return true;
    }
    return false;
  }
  const displayNone = (el) => el instanceof Element && el.getClientRects().length === 0;

  // ---------- numbers, said the way a narrator would ----------
  // The phone's Kokoro reads text through a dictionary, so digits are turned into words first.
  const ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve',
    'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
  const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
  function under1000(n) {
    const h = Math.floor(n / 100), r = n % 100;
    const parts = [];
    if (h) parts.push(ONES[h] + ' hundred');
    if (r) parts.push(r < 20 ? ONES[r] : TENS[Math.floor(r / 10)] + (r % 10 ? '-' + ONES[r % 10] : ''));
    return parts.join(' and ');
  }
  function words(n) {
    if (!Number.isFinite(n)) return String(n);
    if (n === 0) return 'zero';
    if (n < 0) return 'minus ' + words(-n);
    const scales = [[1e12, 'trillion'], [1e9, 'billion'], [1e6, 'million'], [1e3, 'thousand']];
    const out = [];
    for (const [v, name] of scales) if (n >= v) { out.push(under1000(Math.floor(n / v)) + ' ' + name); n %= v; }
    if (n) out.push(under1000(n));
    return out.join(' ').replace(/ and (\w+)$/, ' and $1');
  }
  function yearWords(y) {
    if (y % 1000 < 10 && y >= 2000) return words(y);              // 2005 -> two thousand five
    const a = Math.floor(y / 100), b = y % 100;
    return words(a) + ' ' + (b === 0 ? 'hundred' : b < 10 ? 'oh ' + words(b) : words(b));
  }
  const ORD = { one: 'first', two: 'second', three: 'third', five: 'fifth', eight: 'eighth', nine: 'ninth', twelve: 'twelfth' };
  function ordinal(n) {
    const w = words(n);
    return w.replace(/(\w+)$/, (m) => ORD[m] || (m.endsWith('y') ? m.slice(0, -1) + 'ieth' : m + 'th'));
  }
  function speakNumbers(t) {
    return t
      .replace(/\$(\d[\d,]*)(?:\.(\d{2}))?\b/g, (_, d, c) => { const n = +d.replace(/,/g, ''); return words(n) + (n === 1 ? ' dollar' : ' dollars') + (c && +c ? ' and ' + words(+c) + ' cents' : ''); })
      .replace(/\b(\d{1,2}):(\d{2})\b/g, (_, h, m) => words(+h) + (+m === 0 ? " o'clock" : +m < 10 ? ' oh ' + words(+m) : ' ' + words(+m)))
      .replace(/\b(\d+)(st|nd|rd|th)\b/gi, (_, d) => ordinal(+d))
      .replace(/\b(1[1-9]\d\d|20\d\d)s?\b/g, (m, y) => { const w = yearWords(+y); return m.endsWith('s') ? (w.endsWith('y') ? w.slice(0, -1) + 'ies' : w + 's') : w; })
      .replace(/\b(\d)0s\b/g, (m, d) => TENS[+d].replace(/y$/, 'ies'))         // the 80s -> the eighties
      .replace(/\b\d{1,3}(,\d{3})+\b/g, (m) => words(+m.replace(/,/g, '')))
      .replace(/\b(\d+)\.(\d+)\b/g, (_, a, b) => words(+a) + ' point ' + b.split('').map(x => ONES[+x]).join(' '))
      .replace(/\b\d+\b/g, (m) => (m.length > 15 ? m.split('').map(x => ONES[+x]).join(' ') : words(+m)))
      .replace(/(\d)%/g, '$1 percent');
  }

  // ---------- extracting ----------
  let blocks = [];
  let activeIndex = -1;

  async function extract() {
    let r = S.extract(document, location.href, hiddenEl);
    if (r.roots.length && !r.blocks.length) r = S.extract(document, location.href, displayNone);
    blocks = r.blocks;
    if (r.textApi) {
      try {
        const res = await fetch(r.textApi, { credentials: 'include' });
        if (res.ok) {
          const site = S.profileFor(location.href);
          const api = S.blocksFromApiHtml(await res.text(), site && site.skip);
          if (api.length >= blocks.length) blocks = api.map(b => ({ el: null, text: b.text, pid: b.pid }));
        }
      } catch { /* keep what's on the page */ }
    }
    return r;
  }

  function elOf(b) {
    if (b.el && b.el.isConnected) return b.el;
    if (b.pid) {
      const el = document.querySelector(`p[data-p-id="${CSS.escape(b.pid)}"]`);
      if (el) { b.el = el; return el; }
    }
    return null;
  }

  // Run by the app after every page load. fixes: the pronunciation list; tidy: web-fiction clean-ups.
  async function run(fixes, tidy) {
    try {
      const r = await extract();
      if (!blocks.length) {
        LoudbookNative.onNoChapter(JSON.stringify({ url: location.href, site: r.site, isStorySite: !!S.profileFor(location.href) }));
        return;
      }
      const say = LBSay.makeSayer(LBSay.parseFixes(fixes || ''), { tidy: tidy !== false });
      const chunks = [{ block: -1, text: r.title }, ...LBChunk.chunkBlocks(blocks.map((b, i) => ({ i, text: b.text })))]
        .map(c => ({ block: c.block, text: c.text, say: speakNumbers(say(c.text)) }))
        .filter(c => /[\p{L}\p{N}]/u.test(c.say));            // scene breaks ("* * *") aren't read
      LoudbookNative.onChapter(JSON.stringify({
        url: location.href, site: r.site, siteName: r.siteName, title: r.title, fiction: r.fiction,
        nextUrl: r.nextUrl, prevUrl: r.prevUrl, chunks,
      }));
    } catch (e) {
      LoudbookNative.onNoChapter(JSON.stringify({ url: location.href, error: String(e && e.stack || e) }));
    }
  }

  // ---------- highlight: the paragraph gets a tint, the sentence a stronger mark ----------
  const canMark = typeof CSS !== 'undefined' && CSS.highlights && typeof Highlight === 'function';
  const squash = (t) => t.replace(/[\s​-‍﻿]+/g, '');
  let markedRange = null;
  function markSentence(el, text, offset) {
    markedRange = null;
    if (!canMark) return false;
    CSS.highlights.delete('loudbook-sentence');
    if (!text) return false;
    const pos = [];
    const walk = (node) => {
      for (const n of node.childNodes) {
        if (n.nodeType === 3) { const v = n.nodeValue; for (let k = 0; k < v.length; k++) if (!/[\s​-‍﻿]/.test(v[k])) pos.push([n, k]); continue; }
        if (n.nodeType !== 1) continue;
        if (/^(SCRIPT|STYLE|NOSCRIPT|TEMPLATE|BUTTON)$/.test(n.tagName) || hiddenEl(n)) continue;
        walk(n);
      }
    };
    walk(el);
    const flat = pos.map(([n, k]) => n.nodeValue[k]).join('');
    const key = squash(text);
    if (!key) return false;
    let at = flat.indexOf(key, Math.max(0, (offset || 0) - 8));
    if (at < 0) at = flat.indexOf(key);
    if (at < 0) return false;
    const [sn, so] = pos[at], [en, eo] = pos[at + key.length - 1];
    const r = document.createRange();
    r.setStart(sn, so); r.setEnd(en, eo + 1);
    CSS.highlights.set('loudbook-sentence', new Highlight(r));
    markedRange = r;
    return true;
  }
  function unTint() { const p = blocks[activeIndex]; if (p && p.el && !p.shared) p.el.classList.remove('lb-active'); }
  function highlight(i, text, offset) {
    unTint();
    activeIndex = i;
    const b = blocks[i];
    const el = b && elOf(b);
    if (!el) {
      if (canMark) CSS.highlights.delete('loudbook-sentence');
      if (b && b.pid) { const loaded = document.querySelectorAll('p[data-p-id]'); if (loaded.length) loaded[loaded.length - 1].scrollIntoView({ block: 'end' }); }
      return false;
    }
    if (!b.shared) el.classList.add('lb-active');
    const marked = markSentence(el, text, (offset || 0) + (b.shared && b.base > 0 ? b.base : 0));
    const r = (b.shared && markedRange ? markedRange : el).getBoundingClientRect();
    if (r.top < 60 || r.bottom > innerHeight - 60) {
      if (b.shared && markedRange) window.scrollBy({ top: r.top - innerHeight / 3, behavior: 'smooth' });
      else el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
    return marked;
  }
  function clear() { unTint(); activeIndex = -1; if (canMark) CSS.highlights.delete('loudbook-sentence'); }

  // tap-and-hold a paragraph -> "read from here" is handled by the app; it asks which block is here
  function blockAt(x, y) {
    const el = document.elementFromPoint(x, y);
    if (!el) return -1;
    for (let i = 0; i < blocks.length; i++) { const e = elOf(blocks[i]); if (e && (e === el || e.contains(el))) return i; }
    return -1;
  }

  const style = document.createElement('style');
  style.textContent = `.lb-active{background:rgba(232,170,70,.13)!important;box-shadow:-5px 0 0 rgba(232,170,70,.85)!important;border-radius:3px}
    ::highlight(loudbook-sentence){background-color:rgba(232,170,70,.38)}`;
  (document.head || document.documentElement).appendChild(style);

  // sayText: what the voice is given for a bit of text (for the pronunciation tests)
  const sayText = (t, fixes, tidy) => speakNumbers(LBSay.makeSayer(LBSay.parseFixes(fixes || ""), { tidy: tidy !== false })(t));
  window.LB = { run, highlight, clear, blockAt, speakNumbers, words, sayText };
})();

}
